test("a retryable response is retried before success", async () => {
  const mock = await startMock([
    { status: 429, contentType: "application/json", body: JSON.stringify({ code: "rate_limited" }), headers: { "retry-after": "0" } },
    { status: 200, contentType: "application/json", body: "\"example\"" },
  ]);
  try {
    const client = new TypeshipClient({ baseUrl: mock.url, credentials: {}, maxRetries: 1, retry: { initialDelayMs: 0, maxDelayMs: 0 } });
    await client.generate.downloadPackage({"token":"example"});
    assert.equal(mock.requests.length, 2);
  } finally { mock.close(); }
});

